  "inlineSchema": "// ==================================================\n// EVENTFLOW — SCHÉMA DE BASE DE DONNÉES (PostgreSQL / Neon)\n// ==================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------- ACTEURS ----------\n\nenum UserRole {\n  ORGANIZER // gère ses événements depuis le dashboard web\n  AGENT // scanne les billets depuis l'app mobile/PWA\n  SUPERADMIN // supervision plateforme\n}\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  fullName     String\n  phone        String?\n  role         UserRole @default(ORGANIZER)\n  createdAt    DateTime @default(now())\n\n  organization   Organization? @relation(fields: [organizationId], references: [id])\n  organizationId String?\n\n  // un agent est rattaché à un ou plusieurs événements pour le contrôle d'accès\n  assignedEvents EventAgent[]\n\n  @@index([organizationId])\n}\n\nmodel Organization {\n  id        String   @id @default(cuid())\n  name      String\n  city      String?\n  logoUrl   String?\n  createdAt DateTime @default(now())\n\n  users  User[]\n  events Event[]\n}\n\n// ---------- ÉVÉNEMENTS ----------\n\nenum EventStatus {\n  DRAFT\n  PUBLISHED\n  CANCELLED\n  ARCHIVED\n}\n\nmodel Event {\n  id          String      @id @default(cuid())\n  slug        String      @unique\n  title       String\n  description String      @db.Text\n  category    String // ex: Concert, Festival, Conférence, Sport\n  city        String\n  venueName   String\n  address     String\n  latitude    Float?\n  longitude   Float?\n  coverImage  String\n  startsAt    DateTime\n  endsAt      DateTime\n  status      EventStatus @default(DRAFT)\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  organization   Organization @relation(fields: [organizationId], references: [id])\n  organizationId String\n\n  ticketCategories TicketCategory[]\n  orders           Order[]\n  agents           EventAgent[]\n\n  @@index([organizationId])\n  @@index([status, startsAt])\n  @@index([city, category])\n}\n\n// un agent de contrôle assigné à un événement précis (relation many-to-many)\nmodel EventAgent {\n  id      String @id @default(cuid())\n  event   Event  @relation(fields: [eventId], references: [id])\n  eventId String\n  agent   User   @relation(fields: [agentId], references: [id])\n  agentId String\n\n  @@unique([eventId, agentId])\n}\n\nmodel TicketCategory {\n  id           String    @id @default(cuid())\n  event        Event     @relation(fields: [eventId], references: [id])\n  eventId      String\n  name         String // ex: VIP, Standard, Early Bird\n  description  String?\n  unitPrice    Int // en FCFA, entier — pas de sous-unité\n  quantity     Int // jauge maximale dédiée\n  quantitySold Int       @default(0)\n  salesStart   DateTime?\n  salesEnd     DateTime?\n\n  orderItems OrderItem[]\n\n  @@index([eventId])\n}\n\n// ---------- COMMANDES & PARTICIPANTS ----------\n\nenum OrderStatus {\n  PENDING // en attente de paiement\n  PAID\n  FAILED\n  REFUNDED\n  CANCELLED\n}\n\nenum PaymentMethod {\n  CARD\n  MTN_MOMO\n  MOOV_MONEY\n  ORANGE_MONEY\n}\n\nmodel Order {\n  id            String         @id @default(cuid())\n  event         Event          @relation(fields: [eventId], references: [id])\n  eventId       String\n  buyerFullName String\n  buyerEmail    String\n  buyerPhone    String\n  status        OrderStatus    @default(PENDING)\n  paymentMethod PaymentMethod?\n  paymentRef    String? // référence transaction Stripe / CinetPay / FedaPay\n  totalAmount   Int // en FCFA\n  createdAt     DateTime       @default(now())\n  paidAt        DateTime?\n\n  items   OrderItem[]\n  tickets Ticket[]\n\n  @@index([eventId, status])\n  @@index([buyerEmail])\n}\n\nmodel OrderItem {\n  id               String         @id @default(cuid())\n  order            Order          @relation(fields: [orderId], references: [id])\n  orderId          String\n  ticketCategory   TicketCategory @relation(fields: [ticketCategoryId], references: [id])\n  ticketCategoryId String\n  quantity         Int\n  unitPrice        Int // prix figé au moment de l'achat\n\n  @@index([orderId])\n}\n\n// un Ticket = un billet nominatif individuel scannable (1 QR code unique)\nenum TicketStatus {\n  VALID\n  SCANNED\n  CANCELLED\n}\n\nmodel Ticket {\n  id         String       @id @default(cuid())\n  order      Order        @relation(fields: [orderId], references: [id])\n  orderId    String\n  qrSecret   String       @unique // payload signé encodé dans le QR code\n  status     TicketStatus @default(VALID)\n  holderName String? // peut être personnalisé après achat\n  scannedAt  DateTime?\n  scannedBy  String? // id de l'agent\n  createdAt  DateTime     @default(now())\n\n  scanLogs ScanLog[]\n\n  @@index([orderId])\n  @@index([status])\n}\n\n// ---------- CONTRÔLE D'ACCÈS / SCAN (traçabilité + support offline) ----------\n\nenum ScanResult {\n  VALID\n  ALREADY_SCANNED\n  NOT_FOUND\n  WRONG_EVENT\n  CANCELLED_TICKET\n}\n\nmodel ScanLog {\n  id        String     @id @default(cuid())\n  ticket    Ticket?    @relation(fields: [ticketId], references: [id])\n  ticketId  String?\n  eventId   String // toujours renseigné, même si le billet est introuvable\n  agentId   String\n  result    ScanResult\n  scannedAt DateTime   @default(now())\n  // Un scan peut avoir été fait hors-ligne sur l'app mobile puis synchronisé plus tard :\n  offlineId String?    @unique // id local généré côté SQLite pour dédupliquer à la sync\n  syncedAt  DateTime?\n\n  @@index([eventId, scannedAt])\n  @@index([ticketId])\n}\n",
  "inlineSchemaHash": "27bdea139cb611bb0e6d2a158908f9118b65ac0ef27f37b827926d96465fc846",
